//! T25: Feishu history paging and the text outbox (scenario
//! feishu_text_history_mock). Server responses come from the committed
//! fixture generated by the real service (scripts/context_extended_fixture.py).
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use serde_json::Value;
use vox_agent_desktop_tauri_lib::context_conversation::{
    decode_history_page, decode_receipt, fetch_history, get_receipt, post_text, Applied,
    EntryState, HistoryError, HistoryMode, HistoryPager, HttpOutcome, ItemSource,
    MemoryOutboxStore, Outbox, OutboxError, PagerEvent, SendStatus, MAX_POSTS, MAX_TEXT_BYTES,
};
use vox_agent_desktop_tauri_lib::context_wire::ContextEndpoint;

const TOKEN: &str = "vox_sso_0123456789abcdefghijklmnopqrstuvwxyzAB";
const OWNER: &str = "feishu-0123456789abcdef0123456789abcdef";
const OTHER: &str = "feishu-fedcba9876543210fedcba9876543210";
const DM: &str = "fc_AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
const GROUP: &str = "fc_BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB";
const REVISION: &str = "0123456789abcdef0123456789abcdef";
const CURSOR: &str = "cursor_0123456789abcdefghijklmnopqrstuv";

/// The fixture's conversation cases with placeholders made concrete.
fn cases() -> Vec<Value> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../test/fixtures/context-extended-wire-v1.json"
    ))
    .unwrap();
    let text = text
        .replace("<id-2>", OWNER)
        .replace("<id-3>", DM)
        .replace("<id-4>", GROUP)
        .replace("<epoch-ms>", "1760000000000")
        .replace("<revision>", REVISION)
        .replace("<cursor>", CURSOR);
    let fixture: Value = serde_json::from_str(&text).unwrap();
    fixture["conversations"]["http_cases"]
        .as_array()
        .unwrap()
        .clone()
}

fn case(name: &str) -> Value {
    cases()
        .into_iter()
        .find(|c| c["name"] == name)
        .unwrap_or_else(|| panic!("fixture case {name}"))
}

fn body(name: &str) -> Vec<u8> {
    serde_json::to_vec(&case(name)["response"]["body"]).unwrap()
}

fn sequence() -> Vec<Value> {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../test/fixtures/context-extended-wire-v1.json"
    ))
    .unwrap()
    .replace("<id-3>", DM);
    let fixture: Value = serde_json::from_str(&text).unwrap();
    fixture["conversations"]["status_sequence"]
        .as_array()
        .unwrap()
        .clone()
}

type Mutation = Box<dyn Fn(&mut Value)>;

fn page_with(mutate: impl FnOnce(&mut Value)) -> Vec<u8> {
    let mut value = case("history_own_first_page")["response"]["body"].clone();
    mutate(&mut value);
    serde_json::to_vec(&value).unwrap()
}

#[test]
fn the_real_service_history_page_decodes_with_its_coverage() {
    let page = decode_history_page(&body("history_own_first_page"), GROUP).unwrap();
    assert_eq!(page.mode, HistoryMode::OwnSubmissions);
    assert_eq!(page.mode.coverage(), "own_submissions_only");
    assert_eq!(page.next_cursor.as_deref(), Some(CURSOR));
    let item = &page.items[0];
    assert_eq!(item.source, ItemSource::Submission);
    assert_eq!(item.event_id.as_deref(), Some("conv-3"));
    assert_eq!(item.status, Some(SendStatus::Pending));
    assert!(item.message_id.is_none());
    let last = decode_history_page(&body("history_own_next_page"), GROUP).unwrap();
    assert!(last.next_cursor.is_none());
    // The text never appears in Debug output.
    assert!(!format!("{item:?}").contains("synthetic"));
}

#[test]
fn own_submissions_never_carry_other_members_messages() {
    let foreign = page_with(|v| {
        let item = &mut v["items"][0];
        item["source"] = "feishu".into();
        item["messageId"] = "om_other".into();
        item["status"] = Value::Null;
        item["authorKind"] = "feishu_user".into();
        item["authorId"] = "ou_bob".into();
    });
    assert_eq!(
        decode_history_page(&foreign, GROUP),
        Err(HistoryError::InvalidResponse)
    );
    // The same item is acceptable once the server says a shared policy applies.
    let shared = page_with(|v| {
        v["mode"] = "shared_policy".into();
        let item = &mut v["items"][0];
        item["source"] = "feishu".into();
        item["messageId"] = "om_other".into();
        item["status"] = Value::Null;
        item["authorKind"] = "feishu_user".into();
        item["authorId"] = "ou_bob".into();
    });
    let page = decode_history_page(&shared, GROUP).unwrap();
    assert_eq!(page.mode.coverage(), "shared_since_policy");
}

#[test]
fn malformed_pages_are_refused_whole() {
    assert_eq!(
        decode_history_page(&body("history_own_first_page"), DM),
        Err(HistoryError::ConversationChanged)
    );
    let bad: Vec<Mutation> = vec![
        Box::new(|v| v["hasMore"] = false.into()),
        Box::new(|v| v["nextCursor"] = "short".into()),
        Box::new(|v| v["mode"] = "group_history".into()),
        Box::new(|v| v["policyRevision"] = "x".into()),
        Box::new(|v| v["items"][0]["deleted"] = true.into()),
        Box::new(|v| v["items"][0]["text"] = Value::Null),
        Box::new(|v| v["items"][0]["status"] = "delivered".into()),
        Box::new(|v| v["items"][0]["eventId"] = Value::Null),
        Box::new(|v| v["items"][0]["createdAt"] = "1760000000001".into()),
        Box::new(|v| v["items"][0]["messageId"] = "om_bad/../".into()),
        Box::new(|v| v["items"][0]["text"] = "x".repeat(MAX_TEXT_BYTES + 1).into()),
        Box::new(|v| {
            let first = v["items"][0].clone();
            v["items"].as_array_mut().unwrap().push(first);
        }),
        Box::new(|v| {
            v["items"][0]["placeholder"] = true.into();
            v["items"][0]["text"] = Value::Null;
            v["items"][0]["modelTranslationAllowed"] = true.into();
        }),
    ];
    for mutate in bad {
        assert_eq!(
            decode_history_page(&page_with(|v| mutate(v)), GROUP),
            Err(HistoryError::InvalidResponse)
        );
    }
    // Display names with controls are rendered inert, not trusted.
    let named = page_with(|v| v["items"][0]["authorName"] = "Al\u{202e}ice\n".into());
    let page = decode_history_page(&named, GROUP).unwrap();
    assert!(!page.items[0].author_name.as_ref().unwrap().contains('\n'));
}

fn decoded(
    name: &str,
) -> Result<vox_agent_desktop_tauri_lib::context_conversation::HistoryPage, HistoryError> {
    decode_history_page(&body(name), GROUP)
}

#[test]
fn the_pager_follows_cursors_and_restarts_on_a_consumed_one() {
    let mut pager = HistoryPager::new(GROUP);
    let first = pager.next_request().unwrap();
    assert!(first.cursor.is_none());
    assert!(
        pager.next_request().is_none(),
        "one request in flight at a time"
    );
    assert_eq!(
        pager.apply(&first, decoded("history_own_first_page")),
        PagerEvent::Appended(1)
    );
    let second = pager.next_request().unwrap();
    assert_eq!(second.cursor.as_deref(), Some(CURSOR));
    assert_eq!(
        pager.apply(&second, decoded("history_own_next_page")),
        PagerEvent::Appended(1)
    );
    assert!(pager.complete() && pager.next_request().is_none());
    assert_eq!(pager.items().len(), 2);
    assert_eq!(pager.mode(), Some(HistoryMode::OwnSubmissions));

    // INVALID_CURSOR / AUTHORIZATION_RESET: discard and read from the start.
    let mut pager = HistoryPager::new(GROUP);
    let first = pager.next_request().unwrap();
    pager.apply(&first, decoded("history_own_first_page"));
    let second = pager.next_request().unwrap();
    assert_eq!(
        pager.apply(&second, Err(HistoryError::Restart)),
        PagerEvent::Restarted
    );
    assert!(pager.items().is_empty());
    assert!(pager.next_request().unwrap().cursor.is_none());
}

#[test]
fn a_changed_revision_or_a_late_page_never_mixes_traversals() {
    let mut pager = HistoryPager::new(GROUP);
    let first = pager.next_request().unwrap();
    pager.apply(&first, decoded("history_own_first_page"));
    let second = pager.next_request().unwrap();
    let other_revision = decode_history_page(
        &{
            let mut v = case("history_own_next_page")["response"]["body"].clone();
            v["policyRevision"] = "fedcba9876543210fedcba9876543210".into();
            serde_json::to_vec(&v).unwrap()
        },
        GROUP,
    );
    assert_eq!(pager.apply(&second, other_revision), PagerEvent::Restarted);
    assert!(pager.items().is_empty());

    // A refresh while a page is in flight: the old reply is ignored.
    let mut pager = HistoryPager::new(GROUP);
    let old = pager.next_request().unwrap();
    pager.restart();
    let fresh = pager.next_request().unwrap();
    assert_eq!(
        pager.apply(&old, decoded("history_own_first_page")),
        PagerEvent::Stale
    );
    assert_eq!(
        pager.apply(&fresh, decoded("history_own_first_page")),
        PagerEvent::Appended(1)
    );

    // The same item on two pages means the traversal moved: restart.
    let next = pager.next_request().unwrap();
    assert_eq!(
        pager.apply(&next, decoded("history_own_first_page")),
        PagerEvent::Restarted
    );

    // Other failures keep what is loaded and retry the same cursor.
    let mut pager = HistoryPager::new(GROUP);
    let first = pager.next_request().unwrap();
    pager.apply(&first, decoded("history_own_first_page"));
    let second = pager.next_request().unwrap();
    assert_eq!(
        pager.apply(&second, Err(HistoryError::Unavailable)),
        PagerEvent::Failed(HistoryError::Unavailable)
    );
    assert_eq!(pager.items().len(), 1);
    assert_eq!(
        pager.next_request().unwrap().cursor.as_deref(),
        Some(CURSOR)
    );
}

// ------------------------------------------------------------ mock server

#[derive(Clone)]
struct Route {
    line: String,
    status: String,
    body: String,
}

fn route(line: &str, status: &str, body: Vec<u8>) -> Route {
    Route {
        line: line.to_string(),
        status: status.to_string(),
        body: String::from_utf8(body).unwrap(),
    }
}

fn read_request(stream: &mut TcpStream) -> (String, String, String) {
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .unwrap();
    let mut data = Vec::new();
    let mut buffer = [0u8; 4096];
    loop {
        let n = stream.read(&mut buffer).unwrap_or(0);
        if n == 0 {
            break;
        }
        data.extend_from_slice(&buffer[..n]);
        let text = String::from_utf8_lossy(&data).to_string();
        if let Some(end) = text.find("\r\n\r\n") {
            let length = text[..end]
                .lines()
                .find_map(|l| {
                    l.to_ascii_lowercase()
                        .strip_prefix("content-length:")
                        .map(|v| v.trim().parse::<usize>().unwrap())
                })
                .unwrap_or(0);
            if data.len() >= end + 4 + length {
                return (
                    text.lines().next().unwrap().to_string(),
                    text[..end].to_string(),
                    text[end + 4..].to_string(),
                );
            }
        }
    }
    (String::new(), String::new(), String::new())
}

#[derive(Default)]
struct Seen {
    lines: Vec<String>,
    heads: Vec<String>,
    bodies: Vec<String>,
}

/// Each route answers once, in order of first match.
fn server(routes: Vec<Route>) -> (ContextEndpoint, Arc<Mutex<Seen>>) {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let origin = format!("http://{}", listener.local_addr().unwrap());
    let seen = Arc::new(Mutex::new(Seen::default()));
    let record = seen.clone();
    thread::spawn(move || {
        let mut routes = routes;
        for stream in listener.incoming() {
            let Ok(mut stream) = stream else { return };
            let (line, head, body) = read_request(&mut stream);
            {
                let mut seen = record.lock().unwrap();
                seen.lines.push(line.clone());
                seen.heads.push(head);
                seen.bodies.push(body);
            }
            let found = routes.iter().position(|r| line.starts_with(&r.line));
            let (status, body) = match found {
                Some(index) => {
                    let r = routes.remove(index);
                    (r.status, r.body)
                }
                None => ("404 Not Found".into(), r#"{"detail":"NOT_FOUND"}"#.into()),
            };
            let _ = write!(
                stream,
                "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
        }
    });
    (ContextEndpoint::parse(&origin).unwrap(), seen)
}

#[tokio::test(flavor = "multi_thread")]
async fn history_requests_carry_the_cursor_and_map_refusals() {
    let messages = format!("GET /v1/conversations/{GROUP}/messages");
    let (endpoint, seen) = server(vec![
        route(
            &format!("{messages}?pageSize=1&cursor="),
            "200 OK",
            body("history_own_next_page"),
        ),
        route(
            &format!("{messages}?pageSize=1 "),
            "200 OK",
            body("history_own_first_page"),
        ),
    ]);
    let first = fetch_history(&endpoint, TOKEN, GROUP, None, 1)
        .await
        .unwrap();
    let cursor = first.next_cursor.clone().unwrap();
    let last = fetch_history(&endpoint, TOKEN, GROUP, Some(&cursor), 1)
        .await
        .unwrap();
    assert!(last.next_cursor.is_none());
    {
        let seen = seen.lock().unwrap();
        assert!(seen.lines[1].contains(&format!("cursor={CURSOR}")));
        assert!(seen
            .heads
            .iter()
            .all(|h| h.contains(&format!("authorization: Bearer {TOKEN}"))));
    }

    let refusal = |name: &str| serde_json::to_vec(&case(name)["response"]["body"]).unwrap();
    for (status, body, expected) in [
        (
            "409 Conflict",
            refusal("history_cursor_consumed"),
            HistoryError::Restart,
        ),
        (
            "403 Forbidden",
            refusal("history_forged_conversation"),
            HistoryError::NotPermitted,
        ),
        (
            "401 Unauthorized",
            br#"{"detail":{"code":"AUTH_REQUIRED"}}"#.to_vec(),
            HistoryError::SignInRequired,
        ),
        (
            "429 Too Many Requests",
            br#"{"detail":"READ_LIMIT"}"#.to_vec(),
            HistoryError::ReadLimit,
        ),
        (
            "503 Service Unavailable",
            br#"{"detail":"READ_UNAVAILABLE"}"#.to_vec(),
            HistoryError::Unavailable,
        ),
        ("302 Found", b"{}".to_vec(), HistoryError::Unavailable),
    ] {
        let (endpoint, _) = server(vec![route(&messages, status, body)]);
        assert_eq!(
            fetch_history(&endpoint, TOKEN, GROUP, None, 50).await,
            Err(expected)
        );
    }
    // A forged conversation id or cursor is never sent.
    let (endpoint, seen) = server(vec![]);
    assert!(
        fetch_history(&endpoint, TOKEN, "fc_../../v1/admin", None, 50)
            .await
            .is_err()
    );
    assert!(fetch_history(&endpoint, TOKEN, GROUP, Some("../x"), 50)
        .await
        .is_err());
    assert!(fetch_history(&endpoint, TOKEN, GROUP, None, 51)
        .await
        .is_err());
    assert!(seen.lock().unwrap().lines.is_empty());
}

#[test]
fn receipts_must_answer_the_request() {
    let accepted = body("send_accepted");
    // The fixture's eventId is the server's; bind a matching outbox id.
    let receipt = decode_receipt(&accepted, "conv-1", DM).unwrap();
    assert_eq!(receipt.status, SendStatus::Pending);
    assert!(!receipt.is_final);
    assert!(decode_receipt(&accepted, "conv-2", DM).is_none());
    assert!(decode_receipt(&accepted, "conv-1", GROUP).is_none());
    let sent = serde_json::to_vec(&sequence()[1]["receipt"]).unwrap();
    let receipt = decode_receipt(&sent, "conv-1", DM).unwrap();
    assert_eq!(receipt.message_id.as_deref(), Some("om_sent"));
    for bad in [
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"sent","reason":"DELIVERED","final":true}"#,
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"pending","reason":"QUEUED","final":true}"#,
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"failed","reason":"X","final":false}"#,
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"pending","reason":"QUEUED","final":false,"messageId":"om_x"}"#,
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"delivered","reason":"QUEUED","final":true}"#,
        r#"{"eventId":"conv-1","conversationId":"CONV","status":"pending","reason":"lower case","final":false}"#,
    ] {
        assert!(
            decode_receipt(bad.replace("CONV", DM).as_bytes(), "conv-1", DM).is_none(),
            "{bad}"
        );
    }
}

/// Rewrite a fixture receipt to answer the outbox's own eventId.
fn answer(name: &str, event: &str) -> Vec<u8> {
    let mut value = case(name)["response"]["body"].clone();
    if value.get("eventId").is_some() {
        value["eventId"] = event.into();
    }
    serde_json::to_vec(&value).unwrap()
}

fn sent_receipt(event: &str) -> Vec<u8> {
    let mut value = sequence()[1]["receipt"].clone();
    value["eventId"] = event.into();
    serde_json::to_vec(&value).unwrap()
}

#[tokio::test(flavor = "multi_thread")]
async fn a_lost_reply_is_retried_with_the_same_request_and_polled_to_sent() {
    let mut outbox = Outbox::new(MemoryOutboxStore::default());
    let event = outbox.enqueue(OWNER, DM, "synthetic message").unwrap();
    assert_eq!(
        outbox.store().saved,
        vec![event.clone()],
        "saved before any POST"
    );

    // First POST: the reply is lost.
    let first = outbox.begin_post(OWNER, &event).unwrap();
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::NotAllowed)
    );
    outbox
        .finish_post(OWNER, &event, HttpOutcome::Network)
        .unwrap();
    assert!(matches!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::NotConfirmed(_)
    ));

    // Retry: the server replays the existing submission (fixture send_replay).
    let post = format!("POST /v1/conversations/{DM}/messages ");
    let receipt = format!("GET /v1/conversations/{DM}/receipts/{event} ");
    let (endpoint, seen) = server(vec![
        route(&post, "202 Accepted", answer("send_replay", &event)),
        route(&receipt, "200 OK", answer("send_accepted", &event)),
        route(&receipt, "200 OK", sent_receipt(&event)),
    ]);
    let retry = outbox.begin_post(OWNER, &event).unwrap();
    assert_eq!(
        *first.body, *retry.body,
        "same eventId and text on every attempt"
    );
    let reply = post_text(&endpoint, TOKEN, &retry).await;
    assert_eq!(
        outbox.finish_post(OWNER, &event, reply).unwrap(),
        Applied::Updated
    );
    assert!(matches!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::Accepted(_)
    ));

    for _ in 0..2 {
        let conversation = outbox.poll_target(OWNER, &event).unwrap();
        let reply = get_receipt(&endpoint, TOKEN, &conversation, &event).await;
        outbox.finish_poll(OWNER, &event, reply).unwrap();
    }
    match &outbox.entry(OWNER, &event).unwrap().state {
        EntryState::Final(r) => {
            assert_eq!(r.status, SendStatus::Sent);
            assert_eq!(r.message_id.as_deref(), Some("om_sent"));
        }
        other => panic!("{other:?}"),
    }
    assert!(outbox.poll_target(OWNER, &event).is_none());
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::NotAllowed)
    );
    let seen = seen.lock().unwrap();
    let sent: Value = serde_json::from_str(&seen.bodies[0]).unwrap();
    assert_eq!(
        sent,
        serde_json::json!({"eventId": event, "text": "synthetic message"})
    );
    assert!(!format!("{:?}", outbox.entry(OWNER, &event).unwrap()).contains("synthetic"));
}

#[test]
fn refusals_end_in_the_state_they_mean() {
    let response = |name: &str, status: u16| HttpOutcome::Response {
        status,
        body: serde_json::to_vec(&case(name)["response"]["body"]).unwrap(),
    };
    let mut outbox = Outbox::new(MemoryOutboxStore::default());

    // 409: the eventId is bound to another payload. Never re-keyed or resent.
    let event = outbox.enqueue(OWNER, GROUP, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    outbox
        .finish_post(
            OWNER,
            &event,
            response("send_conflict_other_conversation", 409),
        )
        .unwrap();
    assert_eq!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::Conflict
    );
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::NotAllowed)
    );

    // 403: permission lost; a user retry keeps the eventId.
    let event = outbox.enqueue(OWNER, GROUP, "synthetic message").unwrap();
    let first = outbox.begin_post(OWNER, &event).unwrap();
    outbox
        .finish_post(OWNER, &event, response("send_forged_conversation", 403))
        .unwrap();
    assert_eq!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::Blocked("CONVERSATION_DENIED".into())
    );
    assert_eq!(
        outbox.begin_post(OWNER, &event).unwrap().event_id,
        first.event_id
    );

    // 422 / 413: refused for good.
    let event = outbox.enqueue(OWNER, GROUP, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    outbox
        .finish_post(OWNER, &event, response("send_unknown_field", 422))
        .unwrap();
    assert!(matches!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::Rejected(_)
    ));

    // 429 / 503 / a receipt for another event: not confirmed, safe to resend.
    let event = outbox.enqueue(OWNER, DM, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    outbox
        .finish_post(
            OWNER,
            &event,
            HttpOutcome::Response {
                status: 202,
                body: body("send_accepted"),
            },
        )
        .unwrap();
    assert_eq!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::NotConfirmed("INVALID_RECEIPT".into())
    );

    // A final `unknown` receipt is shown as unknown and never resent.
    let event = outbox.enqueue(OWNER, DM, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    let unknown = format!(
        r#"{{"eventId":"{event}","conversationId":"{DM}","status":"unknown","reason":"RECEIPT_MISMATCH","final":true}}"#
    );
    outbox
        .finish_post(
            OWNER,
            &event,
            HttpOutcome::Response {
                status: 202,
                body: unknown.into_bytes(),
            },
        )
        .unwrap();
    assert!(
        matches!(&outbox.entry(OWNER, &event).unwrap().state, EntryState::Final(r) if r.status == SendStatus::Unknown)
    );
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::NotAllowed)
    );
}

#[test]
fn a_missing_receipt_allows_the_same_request_again_up_to_the_limit() {
    let mut outbox = Outbox::new(MemoryOutboxStore::default());
    let event = outbox.enqueue(OWNER, DM, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    outbox
        .finish_post(
            OWNER,
            &event,
            HttpOutcome::Response {
                status: 202,
                body: answer("send_accepted", &event),
            },
        )
        .unwrap();
    let missing = HttpOutcome::Response {
        status: 404,
        body: body("receipt_other_conversation"),
    };
    outbox.finish_poll(OWNER, &event, missing).unwrap();
    assert_eq!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::NotConfirmed("RECEIPT_NOT_FOUND".into())
    );
    // A receipt that answers something else changes nothing.
    let mut accepted = Outbox::new(MemoryOutboxStore::default());
    let other = accepted.enqueue(OWNER, DM, "synthetic message").unwrap();
    accepted.begin_post(OWNER, &other).unwrap();
    accepted
        .finish_post(
            OWNER,
            &other,
            HttpOutcome::Response {
                status: 202,
                body: answer("send_accepted", &other),
            },
        )
        .unwrap();
    let wrong = HttpOutcome::Response {
        status: 200,
        body: sent_receipt("someone-else"),
    };
    assert_eq!(
        accepted.finish_poll(OWNER, &other, wrong).unwrap(),
        Applied::Ignored
    );
    assert!(matches!(
        accepted.entry(OWNER, &other).unwrap().state,
        EntryState::Accepted(_)
    ));

    for _ in 1..MAX_POSTS {
        outbox.begin_post(OWNER, &event).unwrap();
        outbox
            .finish_post(OWNER, &event, HttpOutcome::Network)
            .unwrap();
    }
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::RetryLimit)
    );
}

#[test]
fn nothing_is_queued_without_a_save_and_text_is_checked_first() {
    let mut outbox = Outbox::new(MemoryOutboxStore {
        fail: true,
        ..Default::default()
    });
    assert_eq!(
        outbox.enqueue(OWNER, DM, "hello").err(),
        Some(OutboxError::StoreUnavailable)
    );
    assert!(outbox.entries(OWNER, DM).is_empty());

    let mut outbox = Outbox::new(MemoryOutboxStore::default());
    for text in ["", "   \n", "a\0b"] {
        assert_eq!(
            outbox.enqueue(OWNER, DM, text).err(),
            Some(OutboxError::InvalidText)
        );
    }
    assert_eq!(
        outbox
            .enqueue(OWNER, DM, &"字".repeat(MAX_TEXT_BYTES / 3 + 1))
            .err(),
        Some(OutboxError::InvalidText)
    );
    assert_eq!(
        outbox.enqueue(OWNER, "oc_raw_chat", "hi").err(),
        Some(OutboxError::InvalidConversation)
    );

    // A failed save before a POST leaves the entry postable and unsent.
    let event = outbox.enqueue(OWNER, DM, "hello").unwrap();
    outbox.store_mut().fail = true;
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::StoreUnavailable)
    );
    assert_eq!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::Queued
    );
    assert_eq!(outbox.entry(OWNER, &event).unwrap().posts, 0);
}

#[test]
fn entries_belong_to_their_owner() {
    let mut outbox = Outbox::new(MemoryOutboxStore::default());
    let mine = outbox.enqueue(OWNER, DM, "mine").unwrap();
    let theirs = outbox.enqueue(OTHER, DM, "theirs").unwrap();
    assert_ne!(mine, theirs);
    assert!(outbox.begin_post(OTHER, &mine).is_err());
    outbox.begin_post(OTHER, &theirs).unwrap();
    // Account switch: the other account's entries go, its late reply is dropped.
    assert_eq!(outbox.retain_owner(Some(OWNER)), 1);
    assert_eq!(
        outbox
            .finish_post(OTHER, &theirs, HttpOutcome::Network)
            .unwrap(),
        Applied::Ignored
    );
    assert_eq!(outbox.entries(OWNER, DM).len(), 1);
    // Not dismissable while a POST may be in flight.
    outbox.begin_post(OWNER, &mine).unwrap();
    assert_eq!(
        outbox.dismiss(OWNER, &mine).err(),
        Some(OutboxError::NotAllowed)
    );
    outbox
        .finish_post(OWNER, &mine, HttpOutcome::Network)
        .unwrap();
    outbox.dismiss(OWNER, &mine).unwrap();
    assert_eq!(outbox.retain_owner(None), 0);
}

#[test]
fn a_failed_save_after_the_reply_never_strands_the_entry() {
    let mut outbox = Outbox::new(MemoryOutboxStore::default());
    let event = outbox.enqueue(OWNER, DM, "synthetic message").unwrap();
    outbox.begin_post(OWNER, &event).unwrap();
    outbox.store_mut().fail = true;
    assert_eq!(
        outbox
            .finish_post(OWNER, &event, HttpOutcome::Network)
            .err(),
        Some(OutboxError::StoreUnavailable)
    );
    // The reply still counts: the same request may be sent again once saving works.
    assert!(matches!(
        outbox.entry(OWNER, &event).unwrap().state,
        EntryState::NotConfirmed(_)
    ));
    assert_eq!(
        outbox.begin_post(OWNER, &event).err(),
        Some(OutboxError::StoreUnavailable)
    );
    outbox.store_mut().fail = false;
    assert_eq!(outbox.begin_post(OWNER, &event).unwrap().event_id, event);
}

#[test]
fn reply_bodies_never_appear_in_debug_output() {
    let outcome = HttpOutcome::Response {
        status: 422,
        body: br#"{"detail":"synthetic secret text"}"#.to_vec(),
    };
    let shown = format!("{outcome:?}");
    assert!(!shown.contains("synthetic") && shown.contains("422"));
}
